const Component = forwardRef((props, ref) => {
  let { enableOrbitControls, settings, base, data, onComponentClick, style = {}, className = '' } = props;

  onComponentClick = onComponentClick || (() => {});
  const containerRef = useRef();
  const [ threeMainComponents, setThreeMainComponents ] = useState();
  const [ lastData, setLastData ] = useState(JSON.parse(JSON.stringify(data)));

  // Expose methods
  useImperativeHandle(ref, () => ({
    exportToImage: () => {
      const canvasElem = threeMainComponents.renderer.domElement;
      const dataSrc = canvasElem.toDataURL("image/png");
      return dataSrc;
    }
  }));

  useEffect(() => {
    loadThreejsDeps().then(() => {

      const scene = new window.THREE.Scene();
      const containerElement = containerRef.current;
      const containerWidth = containerElement.offsetWidth;
      const containerHeight = containerElement.offsetHeight;
      const renderer = new window.THREE.WebGLRenderer( { antialias: true, preserveDrawingBuffer: false } );
      renderer.setPixelRatio( window.devicePixelRatio );
      renderer.setSize( containerWidth, containerHeight );
      containerElement.appendChild( renderer.domElement );
      const mainCamera = new window.THREE.PerspectiveCamera( 70, containerWidth / containerHeight, 1, 5000 );
      mainCamera.position.z = settings.cameraPosition || 500;
      const domEvents	= new window.THREEx.DomEvents(mainCamera, renderer.domElement)

      // Setup Controls
      const orbitControls = new window.THREE.OrbitControls(mainCamera, renderer.domElement);
      orbitControls.enabled = false;

      // Setup mesh groups
      const roofAreasGroup = new window.THREE.Group();
      const treesGroup = new window.THREE.Group();
      scene.add(roofAreasGroup);
      scene.add(treesGroup);

      // Setup base mesh
      const baseGeometry = new window.THREE.BoxGeometry( base.sizeX, base.sizeY, 5 );
      const baseMaterial = new window.THREE.MeshBasicMaterial( { color: 0x333333 } );
      const baseMesh = new window.THREE.Mesh( baseGeometry, baseMaterial );
      scene.add(baseMesh);

      // Store components in state
      setThreeMainComponents({
        scene,
        containerElement,
        renderer,
        mainCamera,
        domEvents,
        orbitControls,
        baseMesh,
        roofAreasGroup,
        treesGroup
      });

      // Start rendering
      function animate() {
        requestAnimationFrame( animate );
        orbitControls.update();
        renderer.render( scene, mainCamera );
      }
      animate();

    });
  }, []);

  // Handle orbit controls
  useEffect(() => {
    if (!threeMainComponents) { return; }
    threeMainComponents.orbitControls.enabled = !!enableOrbitControls;
  }, [threeMainComponents, enableOrbitControls]);

  // Handle base updates
  useEffect(() => {
    if (!threeMainComponents) { return; }
    const baseTexture = resolveTexture(base.imageUrl);
    const baseGeometry = new window.THREE.BoxGeometry( base.sizeX, base.sizeY, 5 );
    const baseMaterial = new window.THREE.MeshBasicMaterial( { map: baseTexture } );
    threeMainComponents.baseMesh.geometry = baseGeometry;
    threeMainComponents.baseMesh.material = baseMaterial;
  }, [threeMainComponents, base])

  // Handle data updates
  useEffect(() => {
    if (!threeMainComponents || !data) { return; }

    // Get items to render
    const noChanges = JSON.stringify(data) == JSON.stringify(lastData);
    const changesMap = {
      trees: !!noChanges || (JSON.stringify(data.trees) != JSON.stringify(lastData.trees)),
      roofAreas: !!noChanges || (JSON.stringify(data.roofAreas) != JSON.stringify(lastData.roofAreas)),
    }

    // Save last data
    setLastData(JSON.parse(JSON.stringify(data)));

    // Render trees
    if (changesMap.trees) {
      while (threeMainComponents.treesGroup.children.length) { threeMainComponents.treesGroup.remove(threeMainComponents.treesGroup.children.pop()) }
      data.trees.forEach(tree => {
        const treeItem = new TreeObject({
          trunkRadius: settings.treesTrunkRadius,
          topRadius: tree.topRadius,
          height: tree.height,
          opacity: tree.opacity || 1,
          position: {
            x: tree.x,
            y: tree.y,
          }
        })
        threeMainComponents.treesGroup.add(
          treeItem.getObject()
        );
      });
    }

    // Roof Areas
    if (changesMap.roofAreas) {
      while (threeMainComponents.roofAreasGroup.children.length) { threeMainComponents.roofAreasGroup.remove(threeMainComponents.roofAreasGroup.children.pop()) }
      data.roofAreas.forEach((shape, raIdx) => {
        const roofAreaItem = new RoofAreaObject({
          path: shape.path,
          surfaceColor: shape.surfaceColor,
          lineColor: shape.lineColor,
          height: shape.height || settings.roofAreaHeight,
          opacity: shape.opacity || settings.defaultRoofAreaOpacity,
          domEvents: threeMainComponents.domEvents
        });
        const roofAreaObject = roofAreaItem.getObject();
        threeMainComponents.roofAreasGroup.add(roofAreaObject);

        // Setup panel groups
        const panelGroups = shape.panelGroups || [];
        panelGroups.forEach((panelGroup, pgIdx) => {

          // Setup panels container
          const panelsGroupItem = new RoofAreaObject({
            path: shape.path,
            surfaceColor: 0xffffff,
            lineColor: shape.lineColor,
            height: (shape.height || settings.roofAreaHeight)+1,
            opacity: 0.3,
            domEvents: threeMainComponents.domEvents
          });
          const panelsGroupObject = panelsGroupItem.getObject();
          threeMainComponents.roofAreasGroup.add(panelsGroupObject);
          panelsGroupItem.onClick(() => {
            onComponentClick({
              path: `roofAreas[${raIdx}].panelGroups[${pgIdx}]`,
              idx: pgIdx,
              item: panelGroup,
              mesh: panelsGroupObject,
            });
          })

          // Setup arrow
          const initPosition = getInitPosition(shape.path);
          const arrowitem = new ArrowObject({
            length: 20,
            color: 0xff0000,
            position: {
              x: initPosition.x,
              y: initPosition.y,
              z: (shape.height || settings.roofAreaHeight)+3,
            },
            rotation: panelGroup.arrowRotation
          });
          const arrowObject = arrowitem.getObject();
          threeMainComponents.roofAreasGroup.add( arrowObject );

          // Setup panels
          const panels = panelGroup.panels || [];
          panels.forEach((panel, pIdx) => {
            const panelItem = new PanelObject({
              panelSizeX: panelGroup.panelsSizeX,
              panelSizeY: panelGroup.panelsSizeY,
              opacity: panel.opacity || 1,
              panelRotation: panel.angle,
              domEvents: threeMainComponents.domEvents,
              position: {
                x: panel.x,
                y: panel.y,
                z: (shape.height || settings.roofAreaHeight)+1,
              }
            })
            const panelObject = panelItem.getObject();
            threeMainComponents.roofAreasGroup.add(panelObject);
            panelItem.onClick(() => {
              onComponentClick({
                path: `roofAreas[${raIdx}].panelGroups[${pgIdx}].panels[${pIdx}]`,
                idx: pIdx,
                item: panel,
                mesh: panelObject,
              });
            })
          })

        });

      })
    }

  }, [threeMainComponents, data])

  return (
    <div ref={containerRef} className={className} style={style}></div>
  )
})

